 "content": "def transform(grid):
    # Remove the 3-colored pattern objects that contain no 9 marker.
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]; marked=False
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=y+dy,x+dx
                    if 0<=a<h and 0<=b<w and grid[a][b] in (3,9) and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
                # 9 markers may be separated? They're embedded in contiguous object.
            # Find 9s adjacent/in component: flood includes them
            marked=any(grid[y][x]==9 for y,x in cells)
            if not marked:
                for y,x in cells: out[y][x]=0
    return out
